			RDF.STEPEngine.SetSPFFHeaderItem(model, 9, 0, RDF.STEPEngine.sdaiSTRING, RDF.STEPEngine.GetSchemaName(model));		//	'AP242_MANAGED_MODEL_BASED_3D_ENGINEERING_MIM_LF  {1 0 10303 442 1 1 4}'

			return model;
		}

