			//	set Preprocessor Version
			RDF.STEPEngine.SetSPFFHeaderItem(model, 6, 0, RDF.STEPEngine.sdaiSTRING, GetLibraryIdentifier());					//	'STEP Engine Library, revision 9999, 2099-12-31T23:59:59'

