		{
			if (IntPtr.Size == 4)
			{
				x86_validateSetOptions((Int32)timeLimitSeconds, (Int32)issueCntLimit, showEachIssueOnce, issueTypes, mask);
			}
			else
			{
				x64_validateSetOptions(timeLimitSeconds, issueCntLimit, showEachIssueOnce, issueTypes, mask);
			}
		}

