		/// <summary>
		/// 
		/// </summary>
		private static long getStringType(long valueType)
		{
			switch (valueType)
			{
				case sdaiSTRING:
				case sdaiUNICODE:
					return sdaiUNICODE;

				case sdaiEXPRESSSTRING:
				case sdaiENUM:
				case sdaiLOGICAL:
				case sdaiBINARY:
					return valueType;
			}
			return 0;
		}

		/// <summary>
		/// 
		/// </summary>
		private static string marshalPtrToString(long valueType, IntPtr ptr)
		{
			if (ptr == IntPtr.Zero)
			{
				return null;
			}

		    switch (valueType)
		    {
				case sdaiUNICODE:
					return Marshal.PtrToStringUni(ptr);

				case sdaiEXPRESSSTRING:
					return Marshal.PtrToStringAnsi(ptr);

				case sdaiENUM:
				case sdaiLOGICAL:
				case sdaiBINARY:
					{
						var unicode = getStringUnicode();
						if (unicode == 0)
							return Marshal.PtrToStringAnsi(ptr);
						else if (unicode == 1 || unicode == 2)
							return Marshal.PtrToStringUni(ptr);
					}
					break;
		    }
		    return null;
		}

		/// <summary>
		/// 
		/// </summary>
		private static byte[] stringToBytes(Int64 valueType, string value)
		{
			switch (valueType)
			{
                case sdaiUNICODE:
                    return Encoding.Unicode.GetBytes(value);

                case sdaiEXPRESSSTRING:
                    return Encoding.ASCII.GetBytes(value);

                case sdaiENUM:
                case sdaiLOGICAL:
                case sdaiBINARY:
                    {
                        var unicode = getStringUnicode();
                        if (unicode == 0)
                            return Encoding.ASCII.GetBytes (value);
                        else if (unicode == 1 || unicode == 2)
                            return Encoding.Unicode.GetBytes(value);
                    }
                    break;

            }
            return null;
		}
    }

