		{
			if (IntPtr.Size == 4)
			{
				var _result = x86_SetCharacterSerialization(model, encoding, wcharBitSizeOverride, ascii);
				return _result;
			}
			else
			{
				return x64_SetCharacterSerialization(model, encoding, wcharBitSizeOverride, ascii);
			}
		}

