		public static Int64 CopyInstanceNetwork(Int64 owlInstance, [param: MarshalAs(UnmanagedType.U1)] bool includeInverseRelations, Int64 targetModel)
		{
			if (IntPtr.Size == 4)
			{
				var _result = x86_CopyInstanceNetwork(owlInstance, includeInverseRelations, targetModel);
				return _result;
			}
			else
			{
				return x64_CopyInstanceNetwork(owlInstance, includeInverseRelations, targetModel);
			}
		}

