		public static Int64 GetClassPropertyByIteratorEx(Int64 model, Int64 owlClass, Int64 rdfProperty, out Int64 minCard, out Int64 maxCard)
		{
			if (IntPtr.Size == 4)
			{
				var _result = x86_GetClassPropertyByIteratorEx(model, owlClass, rdfProperty, out Int64 _minCard, out Int64 _maxCard);
				minCard = _minCard;
				maxCard = _maxCard;
				return _result;
			}
			else
			{
				return x64_GetClassPropertyByIteratorEx(model, owlClass, rdfProperty, out minCard, out maxCard);
			}
		}

